const relevanceOf = (f: NormalizedFinding): number => {
  const t = traceByFinding.get(findingIdOf(f));
  // ★ R15 FIX: the merge above sanitizes (finite numbers only) but this read did
  //   not — a non-numeric relevance coerces/concatenates (the return type lies),
  //   NaN poisons the total (comparator returns NaN, treated as 0), and a null
  //   relevance throws TypeError instead of scoring 0. Same guard as the merge.
  if (!t || t.relevance == null) return 0;
  return Object.values(t.relevance).reduce((s, v) => s + (typeof v === 'number' && Number.isFinite(v) ? Math.max(0, v) : 0), 0);
};

const merged = { ...existing.relevance } as Record<string, number>;
// ★ R19-HIGH FIX (2026-09-25): `Object.entries(null)` and `Object.entries(undefined)`
//   THROW TypeError — the merge loop assumed every trace row carries an object. A row
//   with `relevance: null` (a producer that had nothing to score) aborts the whole merge
//   and takes the report down with it. The spread on the line above is tolerant
//   (`{...null}` is `{}`), which HID the asymmetry: one arm of the same loop tolerates
//   what the other throws on. Both arms now tolerate it.
for (const [k, v] of Object.entries(t.relevance ?? {})) merged[k] = (merged[k] ?? 0) + (typeof v === "number" ? v : 0);

const ordered = [...ranked].sort((a, b) => {
  const ra = relevanceOf(a);
  const rb = relevanceOf(b);
  if (ra !== rb) return rb - ra;
  const sa = severityScore(a.severity);
  const sb = severityScore(b.severity);
  if (sa !== sb) return sb - sa;
  const ia = findingIdOf(a), ib = findingIdOf(b);
  return ia < ib ? -1 : ia > ib ? 1 : 0;
});
